<div class="star-rating">
    <span class="rating-label">Rate this recipe:</span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= CurrentRating ? "filled" : "")"
              @onclick="() => SetRating(star)"
              @onmouseover="() => HoverRating = star"
              @onmouseout="() => HoverRating = 0"
              style="@(star <= (HoverRating > 0 ? HoverRating : CurrentRating) ? "color: gold;" : "color: #ccc;")">
            ★
        </span>
    }
    @if (Submitted)
    {
        <span class="rating-thanks">Thanks for rating!</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double InitialRating { get; set; }

    private int CurrentRating { get; set; }
    private int HoverRating { get; set; }
    private bool Submitted { get; set; }

    protected override void OnParametersSet()
    {
        CurrentRating = (int)Math.Round(InitialRating);
    }

    private void SetRating(int rating)
    {
        CurrentRating = rating;
        Submitted = true;
    }
}

