@page "/"

<PageTitle>Recipe Community</PageTitle>

<div class="container">
    <h1>🍳 Recipe Community</h1>
    <p class="lead">Discover and share delicious recipes from around the world.</p>

    <h2>Browse by Category</h2>
    <div class="row">
        @foreach (var category in RecipeCommunity.Models.RecipeStore.Categories)
        {
            <div class="col-md-4 mb-3">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@GetCategoryEmoji(category) @category</h5>
                        <p class="card-text">@RecipeCommunity.Models.RecipeStore.GetByCategory(category).Count recipe(s)</p>
                        <a href="/recipes/@category.ToLower()" class="btn btn-primary">Browse</a>
                    </div>
                </div>
            </div>
        }
    </div>
</div>

@code {
    private static string GetCategoryEmoji(string category) => category switch
    {
        "Italian" => "🍕",
        "Indian" => "🍛",
        "Mexican" => "🌮",
        "Thai" => "🍜",
        "Desserts" => "🍫",
        "Salads" => "🥗",
        _ => "🍽️"
    };
}

@page "/recipes/{Category}"
@using RecipeCommunity.Models

<PageTitle>@Category Recipes - Recipe Community</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">@Category</li>
        </ol>
    </nav>

    <h1>@Category Recipes</h1>

    @if (recipes.Any())
    {
        <div class="row">
            @foreach (var recipe in recipes)
            {
                <div class="col-md-6 mb-3">
                    <div class="card h-100">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text">
                                <span style="color: gold;">@(new string('★', (int)Math.Round(recipe.AverageRating)))@(new string('☆', 5 - (int)Math.Round(recipe.AverageRating)))</span>
                                <small class="text-muted">(@recipe.RatingCount ratings)</small>
                            </p>
                            <a href="/recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
    else
    {
        <div class="alert alert-info">No recipes found in this category.</div>
    }
</div>

@code {
    [Parameter] public string Category { get; set; } = string.Empty;

    private List<Recipe> recipes = new();

    protected override void OnParametersSet()
    {
        recipes = RecipeStore.GetByCategory(Category);
    }
}

@page "/recipe/{Id:int}"
@using RecipeCommunity.Models
@using RecipeCommunity.Components.Shared

<PageTitle>@(recipe?.Title ?? "Recipe") - Recipe Community</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            @if (recipe is not null)
            {
                <li class="breadcrumb-item"><a href="/recipes/@recipe.Category.ToLower()">@recipe.Category</a></li>
                <li class="breadcrumb-item active">@recipe.Title</li>
            }
        </ol>
    </nav>

    @if (recipe is null)
    {
        <div class="alert alert-warning">Recipe not found.</div>
    }
    else
    {
        <h1>@recipe.Title</h1>
        <p class="text-muted">Category: @recipe.Category | Average Rating: @recipe.AverageRating.ToString("0.0") (@recipe.RatingCount ratings)</p>

        <StarRating RecipeId="@recipe.Id" InitialRating="@recipe.AverageRating" />

        <hr />

        <h3>Ingredients</h3>
        <ul class="list-group mb-4">
            @foreach (var ingredient in recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
            {
                <li class="list-group-item">@ingredient</li>
            }
        </ul>

        <h3>Steps</h3>
        <ol class="list-group list-group-numbered mb-4">
            @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
            {
                var text = System.Text.RegularExpressions.Regex.Replace(step, @"^\d+\.\s*", "");
                <li class="list-group-item">@text</li>
            }
        </ol>
    }
</div>

@code {
    [Parameter] public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeStore.GetById(Id);
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeCommunity.Models

<PageTitle>Submit Recipe - Recipe Community</PageTitle>

<div class="container">
    <h1>Submit a Recipe</h1>
    <p>Share your favorite recipe with the community!</p>

    @if (submitted)
    {
        <div class="alert alert-success">
            <h4>Recipe Submitted!</h4>
            <p>Thank you for sharing "<strong>@title</strong>" with the community.</p>
            <a href="/" class="btn btn-primary">Back to Home</a>
        </div>
    }
    else
    {
        <EditForm Model="@this" OnValidSubmit="HandleSubmit" FormName="recipeForm">
            <div class="mb-3">
                <label for="title" class="form-label">Recipe Title</label>
                <InputText id="title" @bind-Value="title" class="form-control" placeholder="e.g. Grandma's Apple Pie" />
                @if (showValidation && string.IsNullOrWhiteSpace(title))
                {
                    <div class="text-danger">Title is required.</div>
                }
            </div>

            <div class="mb-3">
                <label for="category" class="form-label">Category</label>
                <InputSelect id="category" @bind-Value="category" class="form-select">
                    <option value="">Select a category...</option>
                    @foreach (var cat in RecipeStore.Categories)
                    {
                        <option value="@cat">@cat</option>
                    }
                    <option value="Other">Other</option>
                </InputSelect>
                @if (showValidation && string.IsNullOrWhiteSpace(category))
                {
                    <div class="text-danger">Category is required.</div>
                }
            </div>

            <div class="mb-3">
                <label for="ingredients" class="form-label">Ingredients</label>
                <InputTextArea id="ingredients" @bind-Value="ingredients" class="form-control" rows="6" placeholder="One ingredient per line" />
                @if (showValidation && string.IsNullOrWhiteSpace(ingredients))
                {
                    <div class="text-danger">Ingredients are required.</div>
                }
            </div>

            <div class="mb-3">
                <label for="steps" class="form-label">Steps</label>
                <InputTextArea id="steps" @bind-Value="steps" class="form-control" rows="8" placeholder="One step per line" />
                @if (showValidation && string.IsNullOrWhiteSpace(steps))
                {
                    <div class="text-danger">Steps are required.</div>
                }
            </div>

            <button type="submit" class="btn btn-success">Submit Recipe</button>
        </EditForm>
    }
</div>

@code {
    private string title = string.Empty;
    private string category = string.Empty;
    private string ingredients = string.Empty;
    private string steps = string.Empty;
    private bool submitted;
    private bool showValidation;

    private void HandleSubmit()
    {
        showValidation = true;

        if (string.IsNullOrWhiteSpace(title) || string.IsNullOrWhiteSpace(category)
            || string.IsNullOrWhiteSpace(ingredients) || string.IsNullOrWhiteSpace(steps))
        {
            return;
        }

        var newRecipe = new Recipe
        {
            Id = RecipeStore.Recipes.Max(r => r.Id) + 1,
            Title = title,
            Category = category,
            Ingredients = ingredients,
            Steps = steps,
            AverageRating = 0,
            RatingCount = 0
        };

        RecipeStore.Recipes.Add(newRecipe);
        submitted = true;
    }
}

@page "/"

