                <label for="steps" class="form-label">Steps</label>
                <InputTextArea id="steps" @bind-Value="steps" class="form-control" rows="8" placeholder="One step per line" />
                @if (showValidation && string.IsNullOrWhiteSpace(steps))
                {
                    <div class="text-danger">Steps are required.</div>
                }
            </div>

            <button type="submit" class="btn btn-success">Submit Recipe</button>
        </EditForm>
    }
</div>

@code {
    private string title = string.Empty;
    private string category = string.Empty;
    private string ingredients = string.Empty;
    private string steps = string.Empty;
    private bool submitted;
    private bool showValidation;

    private void HandleSubmit()
    {
        showValidation = true;

        if (string.IsNullOrWhiteSpace(title) || string.IsNullOrWhiteSpace(category)
            || string.IsNullOrWhiteSpace(ingredients) || string.IsNullOrWhiteSpace(steps))
        {
            return;
        }

        var newRecipe = new Recipe
        {
            Id = RecipeStore.Recipes.Max(r => r.Id) + 1,
            Title = title,
            Category = category,
            Ingredients = ingredients,
            Steps = steps,
            AverageRating = 0,
            RatingCount = 0
        };

        RecipeStore.Recipes.Add(newRecipe);
        submitted = true;
    }
}

